from html import escape
PAGES=[]
WIKI='https://dragonwilds.runescape.wiki/w/'
HELP='https://runescapedragonwilds.help.jagex.com/hc/en-gb/articles/'
NEWS='https://dragonwilds.runescape.com/news/'
SOURCES={
 'tutorial':('Jagex · Getting started and the tutorial',HELP+'33779695456017-Getting-started-and-the-tutorial'),
 'controls':('Jagex · Controls and key bindings',HELP+'33780109314833-In-game-controls-and-key-bindings'),
 'craft':('Jagex · Crafting',HELP+'33771293886737-Crafting'),
 'magic':('Jagex · Using Magic',HELP+'33785973124497-Using-Magic'),
 'skills':('Jagex · Skills and the Skill Tree',HELP+'33769638026641-Skills-and-the-Skill-Tree'),
 'build':('Jagex · Build mode',HELP+'33770561286417-Build-mode'),
 'journal':('Jagex · Using the Journal',HELP+'33776445837201-Using-the-Journal'),
 'launch':('Jagex · 1.0 release notes · 15 September 2026',NEWS+'launch'),
 'summit':('Jagex · RuneFest Summit · 3 October 2026',NEWS+'runefest-2026'),
 'agility':('Jagex · Agility update · 29 July 2026',NEWS+'0.12.1-update'),
 'game':('Jagex · About RuneScape: Dragonwilds','https://dragonwilds.runescape.com/'),
}
def p(t):return '<p>'+t+'</p>'
def ul(items):return '<ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul>'
def ol(items):return '<ol class="steps">'+''.join('<li>'+x+'</li>' for x in items)+'</ol>'
def note(t,title='Field note'):return '<aside class="note"><strong>'+title+'</strong><p>'+t+'</p></aside>'
def pic(n,caption):return '<figure><a class="zoom" href="assets/media/'+n+'.png" aria-label="Enlarge: '+escape(caption,quote=True)+'"><img loading="lazy" src="assets/media/'+n+'.png" alt="'+escape(caption,quote=True)+'"></a><figcaption>'+caption+' <span>Click to enlarge</span></figcaption></figure>'
def table(headers,rows,filterable=False):
 return ('<label class="table-filter">Filter this reference<input type="search" data-table-filter placeholder="Type a resource, action or skill…"></label>' if filterable else '')+'<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def check(id,items):return '<div class="checklist" data-checklist="'+id+'"><div class="check-head"><strong>Your checklist</strong><span class="check-count" aria-live="polite"></span></div>'+''.join('<label><input type="checkbox" data-check="'+id+'-'+str(i)+'"><span>'+x+'</span></label>' for i,x in enumerate(items))+'<p class="small">Saved on this browser only. Tick items as you go.</p><button class="text-button reset-check" type="button">Reset this checklist</button></div>'
def disclosure(t,b):return '<details><summary>'+t+'</summary>'+b+'</details>'
def link(slug,title):
 parts=slug.split('#',1)
 return '<a href="'+parts[0]+'.html'+('#'+parts[1] if len(parts)>1 else '')+'">'+title+'</a>'
def add(slug,title,group,desc,sections,wiki,sources=[],icon='◇',related=[]):
 PAGES.append(dict(slug=slug,title=title,group=group,desc=desc,sections=sections,wiki=wiki,sources=sources,icon=icon,related=related))

add('overview','The world of Dragonwilds','Start here','A strange continent. Familiar RuneScape roots. An adventure you build together.',[
('A new adventure in the RuneScape universe',p('Dragonwilds is a survival crafting game set on Ashenfall, a forgotten continent in RuneScape’s world. You move, aim and fight directly, gather materials and build a home. You do not need to have played RuneScape or Old School RuneScape to start.')+p('Ashenfall is rich in <strong>anima</strong>, the magical energy that helps explain its extraordinary landscape and powerful skill spells. Ruins and old accounts reveal what happened here. Familiar faces such as the Wise Old Man, Doric and Zanik connect this frontier to the wider RuneScape setting.')),
('What am I trying to achieve?',p('The original Kuldra Saga builds towards confronting the Dragon Queen, Kuldra. Treat that as the long-term destination. Your first useful victory is much smaller: reach camp, learn how to feed and equip yourself, and return safely from a gathering trip.')+table(['Horizon','A useful goal'],[['First session','Join DragonInfinity, reach camp and claim an available bed.'],['Next few sessions','Understand your equipment, choose a combat style and contribute supplies.'],['The longer adventure','Explore further regions, follow quests and prepare for major encounters with the group.'],['Your own goals','Build a home, master skills, collect equipment or become the team’s cook and supplier.']])+note('Progress is a loop: gather useful materials, turn them into supplies, explore a little further, then come home better prepared. You do not need to complete every system at once.')),
('What makes DragonInfinity different?',p('DragonInfinity is the shared server hosted by <strong>S3RVNetwork, part of S3rvStudios</strong>. Its custom settings can change how quickly you progress and how dangerous the world feels. This guide teaches the underlying game and uses our own screenshots for the server-specific steps.')+p('The supplied server-browser screenshot shows PvP and crossplay enabled. That is a snapshot, not a live status feed. Check <strong>View Details</strong> before joining and follow the host’s current rules.')+link('community','Read the server etiquette')),
('2026 / 2027 roadmap',p('Jagex’s announced plans, summarised from the 3 October 2026 Summit. These are future plans, not features to look for in your current menus. Dates and scope can change.')+'<div class="timeline"><div><span class="eyebrow">DECEMBER 2026 · PLANNED</span><h3>Luminance</h3><p>Prayer, elven customisation and building pieces, the Lyre, Songstones and Fairy Ring journeys. A prelude to the next saga.</p></div><div><span class="eyebrow">FIRST HALF OF 2027 · PLANNED</span><h3>Song of Rebellion</h3><p>The Blood Crystal Saga opens in Ailddinas, with rebel elves, the Nos Clan and the Hunter skill. Official modding tools, an in-game mod browser, Secure Servers and Leaderboards are also targeted for this window.</p></div><div><span class="eyebrow">LATER CHAPTER · ANNOUNCED</span><h3>Crown of Night</h3><p>The story continues into the Nos Clan’s eclipsed lands, with the Light of Seren and legendary equipment. Consult Jagex for the latest release timing.</p></div></div>'+p('<a href="'+NEWS+'runefest-2026" target="_blank" rel="noopener">Read Jagex’s full announcement and view the official roadmap artwork</a>'))
],['Ashenfall','Kuldra'],['game','summit','launch'],icon='◎',related=['getting-started','quests','bosses'])

add('connect','How to connect','Start here','Find the right world, choose your character and join DragonInfinity.',[
('Before you join',ul(['Install and update RuneScape: Dragonwilds on your platform. Let the update finish before launching.','Have the server password ready: <strong>RSDW</strong>. It is case-sensitive; ask the host if it has changed.','Use the character you want to play. Double-check the name before entering the world.'])+pic('CharacterSelect','The character-selection screen: choose the adventurer you want to bring.')),
('Find DragonInfinity',ol(['Open the multiplayer <strong>Worlds</strong> browser. Select <strong>Public</strong>, as shown below.','Search for <strong>DragonInfinity</strong>. If filters are hiding custom or password-protected worlds, adjust them and search again.','Select the matching world. The supplied screenshot shows creator <strong>-S3RV-RSDW</strong>; confirm the name and host rather than joining a similarly named world.','Choose <strong>View Details</strong> to inspect the current settings. Select <strong>Enter World</strong>, enter <strong>RSDW</strong> and confirm.','Once you load in, follow '+link('getting-started','the first-session guide')+' and '+link('basecamp','the route to camp')+'.'])+'<button class="button secondary" data-copy="DragonInfinity">Copy server name</button>'+pic('HowToConnect','Public world search for DragonInfinity. Player count and settings are a captured example, not live server information.')),
('Enter the server password',p('The password supplied for this edition is <strong>RSDW</strong>. Enter it exactly as shown, then confirm. If it stops working, check with the host for an updated password.')+'<button class="button secondary" data-copy="RSDW">Copy password</button>'+pic('HowToEnterPassword','Enter RSDW in the password field, then confirm to join DragonInfinity.')),
('If the world does not appear',ul(['Clear the search and retype the exact name. Recheck world-browser filters.','Check your game has finished updating. The server may also need to update or restart.','Check the crossplay settings shown by your game and the server. Ask the host whether your platform is currently supported.','Ask the host whether the server is online and whether the name has changed. Repeatedly creating local worlds will not connect you to this server.'])+note('A direct address or invite code is an alternative only when supplied by the host. Do not use 127.0.0.1 on your own PC to reach a remotely hosted server; that address refers to your own computer.','Direct connection')),
('If a password or connection fails',p('Retype the password carefully, checking capitals and accidental spaces. If it still fails, ask for the current password. For a connection error, record the exact message and your game version for the host. Never send account passwords or login codes.')+link('troubleshooting','More connection and gameplay fixes'))
],['Multiplayer'],['launch'],icon='⌁',related=['getting-started','basecamp','community'])

add('getting-started','Your first session','Start here','From your first login to a bed at camp, without assuming you know the genre.',[
('1. Get your bearings',p('Join '+link('connect','DragonInfinity')+' first. A new adventurer begins at the ruined Temple of Saradomin in Temple Woods. Learn movement, interacting and opening the map before you wander away. Speak to the Wise Old Man nearby.')+note('Your immediate goal is to reach the group with a little food, usable equipment and a clear idea of where you are. You do not have to fight every creature on the way.')),
('2. Choose your start', '<div class="two-col"><div class="panel"><span class="eyebrow">RECOMMENDED FOR NEW PLAYERS</span><h3>Play the tutorial</h3><p>Accept the Wise Old Man’s introductory lessons. Doric introduces survival and crafting, Vannaka covers early combat and cooking, and Zanik introduces magic. This gives you guided practice before you depend on the group.</p></div><div class="panel"><span class="eyebrow">FASTER ROUTE TO FRIENDS</span><h3>Skip the lessons</h3><p>Decline the tutorial when the Wise Old Man offers it. You can head towards camp sooner, but you miss the guided explanation. Ask someone to meet you, and learn the essential actions below before venturing out alone.</p></div></div>'+p('Skipping the tutorial is not a grant of high-level equipment or protection. Confirm what starter supplies the host is offering. Follow the current dialogue rather than looking for a specific button label from an older video.')),
('3. Learn the essentials',ol(['<strong>Gather:</strong> pick up useful loose materials. Read the object name before interacting.','<strong>Craft:</strong> open a suitable workbench, select a recipe and check its ingredients. Craft one useful item before attempting a whole equipment set.','<strong>Equip:</strong> put the tool or weapon on your quick-access bar and select it. Having something in your bag does not mean it is in your hand.','<strong>Fight:</strong> practise attacking, blocking and dodging where there is room to retreat. Stop attacking before your stamina is exhausted.','<strong>Navigate:</strong> open the map, identify your own marker and compare it with the camp map. Use the compass to maintain your direction.'])+pic('AbilityBarAndInventoryAndPowerLevel','Inventory, quick-access slots and equipped armour. Check what is actually equipped before leaving camp.')),
('4. Follow the tutorial, if you chose it',p('Doric sends you for water and introduces the Crafting Table and Stone Club. Vannaka’s rat hunt leads into campfire cooking. Zanik teaches rune preparation and a gathering spell. Read each active objective before gathering: the quest log tells you what the game currently expects.')+p('When the introductory lessons are complete, the Wise Old Man awaits in Bramblemead Village. The village quest destination and our clan camp are different places; use the camp route below to find the group.')),
('5. Reach camp and settle in',p('Follow '+link('basecamp','the annotated route to basecamp')+'. Ask which beds and chests are free. Claim an available bed through its interaction prompt and confirm your own bed marker. Put spare materials in the correct storage, then ask what the group needs next.')+check('first-session',['I joined the correct DragonInfinity world.','I can open the map, inventory and controls.','I chose the tutorial or arranged help from another player.','I reached camp and claimed an available bed.','I know which storage is communal and which is personal.','I have food and usable equipment for a short trip.','I know how to return to camp.']))
],['First_Steps','Getting_Started','Rune_Mysteries'],['tutorial','controls'],icon='✦',related=['basecamp','keybinds','safety'])

add('basecamp','Find basecamp','Start here','A practical route from Temple Woods to the DragonInfinity clan village.',[
('The route at a glance',pic('HowToGetToClanVillage','Host-supplied route: leave the western temple ruins, travel east through Temple Woods, then north-east to the circled camp south of Bramblemead Valley.')+note('The circled bed belongs to the player who took this screenshot. It is a location reference; it will not automatically be your claimed bed. Player markers and buildings can change.','Read the map correctly')),
('Walk the route',ol(['<strong>Start at the temple ruins</strong> on the western edge of the map. Open your map and identify your own player marker.','<strong>Travel east through Temple Woods.</strong> Use the red line as the broad direction, choosing walkable ground around trees and rocks.','<strong>Turn north-east towards the circled area.</strong> It sits south of the large Bramblemead Valley label, close to the cluster of bed icons in the supplied map.','<strong>Ask for a meet-up if you lose the route.</strong> Share a screenshot of your map or describe the nearest named location. Do not continue into unfamiliar dangerous terrain just because it appears to be a shortcut.','<strong>At camp, check before claiming a bed or using storage.</strong> Ask the host or a player to show you communal supplies and workstations.'])+p('This is an orientation guide from the host’s annotated image, not a measured turn-by-turn route. The red stroke does not identify every path junction.')),
('Use your compass',pic('Compass','The compass shows directions and marker distances. The distance in this screenshot is an example.')+p('Face the marker you want to follow, then keep checking whether its distance is decreasing. If you reach a cliff, water or enemies, go around and recheck the map. A compass direction does not guarantee a safe straight-line path.')),
('Make the return easy',p('Before leaving, identify your bed marker and mark camp if your map allows it. Keep a mental note of the last landmark you passed. On a first trip, turn back while you still have food and working equipment.')+note('Home Teleport is an unlock with rune and cooldown requirements in the standard game. Do not assume a new character can teleport home immediately. Read your current spell description and check the server settings.'))
],['Temple_Woods','Bramblemead_Valley'],['launch'],icon='⌖',related=['getting-started','safety','resources'])

add('keybinds','Keybinds & controls','The essentials','A compact reference for keyboard, mouse and Xbox-style controller prompts.',[
('Find your actual bindings',p('Open <strong>Esc → Settings → Controls</strong>. Rebound keys and platform layouts can differ. The reference below combines Jagex’s keyboard guide with the 1.0 controller changes and the supplied screenshots. The on-screen action prompt always takes priority.')+note('In 1.0, primary attack moved to RB/R1/R and special attack to RT/R2/ZR. Some older guides still show the reverse.','Controller change')),
('Movement and interaction',table(['Action','Keyboard / mouse','Xbox-style'],[['Move','W A S D','Left stick'],['Look','Mouse','Right stick'],['Jump','Space','A'],['Sprint','Shift','Left-stick press'],['Interact','E','X'],['Secondary interact','F','Follow prompt'],['Evade / dodge','Ctrl','B'],['Primary attack / chop','Left mouse','RB'],['Block / secondary action','Right mouse','LT'],['Special attack','Middle mouse','RT']],True)),
('Menus and quick access',table(['Action','Keyboard','Xbox-style'],[['Inventory','Tab','Y'],['Map','M','Menu / map prompt'],['Journal','J','Menu tabs'],['Skills','K','Menu tabs'],['Spellbook','P','Menu tabs'],['Spell wheel','Q','LB'],['Building','B','D-pad down'],['Quick-access slots','1–8','Use quick-access wheel'],['Exit / pause menu','Esc','Menu / B to back out']])),
('Build, inspect, then place',p('In Build mode, keyboard players can use Q/E for categories, Y for free placement, T for repair and Esc to cancel. Always read the active mode: an input used to attack in the world may place or remove something while building.')+pic('WoodcuttingHowTo','Controller prompts while holding an axe: Chop RB, Overhead Chop RT, Block LT and Evade B.')+pic('RadialWheel','A radial selection wheel. Pause somewhere safe while learning how its slots work.')),
('Make the controls comfortable',ul(['Practise dodge and block before entering a tough fight.','If two actions conflict after rebinding, review both affected menus.','Keep the camera sensitivity low enough that you can turn without losing track of your target.','Try a short gathering trip after changing your controls; it is easier to discover a bad binding there than during a boss fight.']))
],['Settings'],['controls','magic','launch'],icon='⌘',related=['combat','magic','building'])

add('skills','Skill guide','The essentials','Learn by doing, choose your next unlock and understand what your levels mean.',[
('Skill level is not equipment power',p('<strong>XP</strong> means experience points. Performing relevant activities advances skills and unlocks benefits. Open <strong>K</strong> and select a skill to inspect its milestones. A high skill level is not the same thing as a high equipment power level: keep your tools and armour appropriate for what you are attempting.')+pic('SkillsOverview','The Skills screen shows current XP and upcoming milestones. This player’s levels are examples, not starter levels.')),
('Choose a useful skill to work on',table(['Skill','What to focus on','Why it helps'],[['Attack','Practise melee combat.','Close-range fighting and related unlocks.'],['Ranged','Use bows or other ranged equipment.','Fight from a distance; plan ammunition.'],['Magic','Use magical combat equipment.','A different combat style with rune needs.'],['Mining','Gather stone and ore with a suitable pickaxe.','Supplies for equipment and construction.'],['Woodcutting','Chop suitable trees with an axe.','Fuel, timber and wood-based materials.'],['Artisan','Make useful equipment and processed items.','Support the team’s crafting needs.'],['Construction','Build useful structures and furnishings.','Create a functional shared camp.'],['Cooking','Prepare food for expeditions.','Keep the team supplied.'],['Runecrafting','Prepare runes for the spells you use.','Support sorcery and utility.'],['Farming','Develop a regular crop-supply routine.','Help sustain cooking and crafting.'],['Fishing','Learn available catches and fishing tools.','Broaden your food supply.'],['Agility','Practise the game’s traversal activities.','Movement-focused progression.']],True)),
('A beginner-friendly training plan',ol(['Pick a real need: food, a better tool or building materials.','Open the relevant skill and read the next milestone. Set one achievable goal.','Gather or craft enough for that goal rather than carrying everything you find.','Return to camp, use what you made and check the next unlock.','Tell the group what you are working on so everyone is not competing for the same supplies.'])+note('DragonInfinity uses custom settings. XP speed may differ from standard-world videos. Look at the XP you actually gain; no multiplier is assumed in this guide.')),
('Turn an unlock into something useful',p('A newly unlocked spell may still need assigning and runes. Read '+link('magic','the magic and spellbook guide')+' before assuming it is ready to cast. Passive benefits and active spells behave differently: inspect the milestone text to see which you gained.')+p('<strong>Prayer and Hunter:</strong> these are announced additions in the '+link('overview#2026-2027-roadmap','roadmap')+'. Do not plan a current training session around unreleased skills.'))
],['Skills'],['skills','agility','launch','summit'],icon='✧',related=['magic','crafting','resources'])

add('magic','Magic & the spellbook','The essentials','Use RuneScape’s sorcery to support exploration, gathering and combat.',[
('Three things you need',p('A skill spell needs to be unlocked, assigned and supplied with the right runes. Rune essence is a material; runes are the items spells consume. A locked spell is a progression issue, while an unlocked spell that will not cast may be missing runes or still on cooldown.')+ol(['Open the Spellbook with <strong>P</strong> on the default keyboard layout.','Inspect the spell: read its effect, rune costs and cooldown.','Put it into a slot on the spell wheel.','Open the wheel with <strong>Q</strong>, select the spell and follow the targeting prompt.'])+pic('SpellbookOverview','The spellbook lists spells and lets you organise the casting wheel.')),
('How you unlock spells',p('Zanik introduces the Spellbook in the tutorial. You can also gain access by reaching your first skill-spell unlock through training. Skills other than Magic can unlock utility spells, so a melee fighter can still benefit from learning sorcery.')+p('Useful priorities depend on your job. A regular gatherer can look for gathering abilities; an explorer may favour movement and return options. Read the description before spending runes on an unfamiliar effect.')),
('Why will my spell not cast?',table(['Check','What to do'],[['Locked icon','Inspect the skill milestone that unlocks it.'],['Missing runes','Compare the exact rune types and quantities, not just your total rune count.'],['Unassigned spell','Put it on the wheel before trying to select it.'],['Cooldown','Wait for the timer to finish.'],['Invalid target','Aim at a valid object or location and follow the prompt.'],['No safe opening','Move away from enemies before testing the spell.']])),
('Use magic responsibly at camp',p('Practise area effects away from buildings, planted trees and other players. Ask before using destructive gathering abilities near the village. Keep spare runes in your own storage and tell the team if you are using a communal supply.'))
],['Magic','Runecrafting'],['magic'],icon='✴',related=['skills','combat','resources'])

add('quests','Quest guide','Adventure & progression','Understand the journal, follow objectives and keep the group’s story together.',[
('How to follow a quest',ol(['Speak to the relevant character or interact with the quest object. Read the dialogue before closing it.','Open your map or quest list and select the objective you are actually working on.','Read the action word: <em>speak, collect, craft, visit</em> and <em>defeat</em> are different tasks.','Use its marker as a destination, then inspect the area on arrival. The marker may not sit directly on the exact object.','After completing the task, recheck the log. Some stages need a return conversation or an item in your inventory.'])+pic('StarterMap','The map and quest list help you compare your selected objective with your location.')),
('Learn the markers',pic('QuestMarker1','A quest-related marker in the Bramblemead area. Select the quest to understand what it represents.')+pic('QuestMarker2','Several quest objectives can appear in one region. Read the active stage before choosing a destination.')),
('Your early route',table(['Stage','Purpose','What to do next'],[['First Steps / tutorial introduction','Meet the Wise Old Man and choose your start.','Learn the essentials or arrange help reaching camp.'],['Getting Started','Doric’s survival and crafting lesson.','Use your own objective list to finish the requests.'],['Ratcatcher','Vannaka’s introductory combat and cooking lesson.','Practise safe attacks and preparing supplies.'],['Rune Mysteries','Zanik’s introduction to runes and sorcery.','Try your spell and understand its rune cost.'],['Dragon Slayer','A longer objective to work towards.','Coordinate with the group; it is not a fight to rush on arrival.']])),
('Beyond your first region',p('Later questing takes you through more demanding parts of Ashenfall. Withering Heights is associated with Fellhollow and Imaru. The 1.0 release adds Regicide in the Scorned Wilderness. Treat these as long-term milestones, not errands to attempt with starter tools.')+disclosure('Story spoilers: the late-game destination',p('Kuldra is the culminating boss of the original saga. Reaching her is a team preparation project: gear, supplies, quest readiness and knowledge of the encounter all matter.'))+note('On DragonInfinity, arrange major story progress with the group. Tell others before you trigger a boss or advance a shared milestone. Give absent players a chance to catch up.','Playing together')),
('If a quest appears stuck',ul(['Read the exact stage again, including item quantities.','Check whether the required item is in your own inventory rather than a chest.','Return to the quest giver and look for a new dialogue option.','Compare your progress with another player; being in the same world does not prove your personal objective is complete.','Look up the named quest using the wiki links below. If the stage still fails, capture the objective and error for the host.']))
],['Quests','First_Steps','Dragon_Slayer','Withering_Heights'],['tutorial','journal','launch'],icon='⚑',related=['bosses','basecamp','community'])

add('crafting','Crafting guide','The essentials','Turn what you gather into equipment, supplies and a reason to explore further.',[
('Start at the right workstation',p('Open Build mode and place a Crafting Table where you have permission, or use the camp’s existing one. Interact with it, select a category and inspect the item. Its recipe shows what you need; the craft control creates it when the requirements are met.')+pic('CraftingTable','Select an item at the Crafting Table to inspect its ingredients and craft quantity.')),
('Read a recipe backwards',ol(['Choose the finished item you need. Check that it suits your current goal.','Write down the missing ingredients. Separate raw materials from processed materials.','For each processed ingredient, find its own recipe and workstation.','Gather the missing raw materials, process them, then return to the final station.','Craft a small amount first. Check the result before spending the group’s entire stock.'])+note('A useful recipe chain might run from ore to a metal bar, then to equipment. The important question is not just “do I have ore?” but “have I processed the right material at the right station?”')),
('Workstation planner',table(['Need','Look for','Beginner advice'],[['Starter tools and equipment','Crafting Table','Read the item category and ingredient panel.'],['Cooked supplies','Campfire / cooking facilities','Check input, fuel and output before leaving.'],['Smelted metal','Furnace','Match the bar recipe and fuel requirements.'],['Metal equipment','Smithing Anvil','Bars may be only part of the recipe.'],['Fabric and thread','Spinning / weaving facilities','Trace the ingredients back to their raw source.'],['Runes','Rune Altar','Make the specific types your spell consumes.']],True)+p('Not every recipe belongs at the basic table. If an item is missing, consult your Journal or the wiki for its station and unlock requirements.')),
('Cooking and clean supplies',pic('Campfire_basicCooking','The campfire interface has input and fuel slots. Check the output and start the process.')+p('Choose the intended input, add appropriate fuel and start cooking. Collect the output before heading off. Keep raw ingredients separate from ready-to-use supplies so you do not accidentally leave camp with a bag of uncooked food.')),
('Repair before replacing',p('Durability measures wear. Inspect your gear and repair at the appropriate facility rather than immediately making another copy. Read the repair cost before confirming; a trip may need both gathering supplies and repair materials.')+pic('JournalOverview','The Journal’s recipe view records item requirements and descriptions for reference.'))
],['Crafting','Crafting_Table','Bronze_Platebody'],['craft','journal'],icon='⚒',related=['resources','building','skills'])

add('combat','Combat guide','Adventure & progression','Learn a repeatable fighting rhythm before worrying about perfect equipment.',[
('Your first safe fight',ol(['<strong>Choose the ground.</strong> Avoid edges, deep water and groups of enemies. Leave yourself somewhere to retreat.','<strong>Watch first.</strong> Let the enemy begin an attack so you can recognise its wind-up.','<strong>Defend.</strong> Block or dodge the attack rather than trading hits until someone falls over.','<strong>Reply briefly.</strong> Attack during the opening, then stop before you exhaust your stamina.','<strong>Reset.</strong> Reposition and repeat. Heal or leave if the fight is going badly.'])+note('Stamina is your action budget. Spending every last bit on attacks can leave you unable to avoid the next hit. Keeping a little in reserve is often worth more than one extra swing.')),
('Choose a style to learn',table(['Style','What it asks of you','A sensible first habit'],[['Melee','Fight close enough to be hit.','Practise defending and short counterattacks.'],['Ranged','Aim while managing distance and ammunition.','Check ammo before leaving and keep a retreat route.'],['Magic','Manage your weapon, runes and casting openings.','Know what each attack costs before a long fight.']])+p('Try the equipment available to you before committing all your resources to one style. Use item descriptions to compare damage, protection and set effects. Better equipment will not remove the need to react.')),
('Power, health and special attacks',p('Inspect your equipped items and power level in the inventory. If an encounter feels far beyond you, improve your equipment and preparation or return with the team. Do not judge your readiness from a single high skill level.')+p('The 1.0 combat update gives special attacks their own recharging bar. Save these attacks for a useful opening. The same update changes parry behaviour, so old videos may not match what you see. Use your current game’s prompts and tooltips.')+pic('AbilityBarAndInventoryAndPowerLevel','Review your equipment, quick-access slots and power indicator before a fight.')),
('Fighting with the group',ul(['Agree who will engage first and where everyone will stand.','Give ranged players a clear view and do not drag enemies into an unprepared teammate.','Call out when you need to retreat. A coordinated reset is better than a chain of recovery runs.','Check the server’s PvP setting. The supplied browser image shows it enabled; avoid testing attacks beside teammates.','Before a major encounter, use the '+link('bosses','boss preparation checklist')+'.']))
],['Combat'],['launch'],icon='⚔',related=['bosses','safety','magic'])

add('bosses','Boss guide','Adventure & progression','Prepare for the encounter, learn its signals and fight as a team.',[
('Be ready before you trigger it',p('Bosses are substantial encounters, not simply larger versions of the first creature you fought. A failed attempt can cost time and supplies. Arrange a start time, compare readiness and make sure everyone knows where to regroup.')+check('boss-prep',['The group agreed to start this encounter.','My current quest stage allows me to take part.','My weapon, armour and tools are repaired.','I have food, relevant protection and enough ammunition or runes.','My return point and recovery route are understood.','I have read the current encounter guide.','Everyone knows when to retreat and where to regroup.'])),
('Major encounters to work towards',table(['Encounter','Where it fits','Preparation focus'],[['Velgar','The early dragon-slaying goal.','Learn your combat rhythm and follow Dragon Slayer preparation.'],['Imaru','Fellhollow’s revenant dragon.','Finish the relevant regional quest steps and learn the local hazards.'],['Black Knight Titan','A major Dowdun Reach encounter.','Bring region-appropriate equipment and understand the approach.'],['Kalphite Queen / Fuzan','Major threats in the Umbral Sands update.','Prepare for the region before committing to an encounter.'],['Kuldra','The Scorned Wilderness and original saga finale.','Coordinate endgame gear, quest progress and a full team plan.']])+p('This is a preparation guide and encounter directory. For exact phases, summons, weaknesses and current item requirements, use the named wiki encounter links below before setting out.')),
('A good first attempt',ol(['Spend the opening watching the boss’s movement and attack signals.','Move out of obvious danger before trying to finish a combo.','Use short attacks during recovery windows, then reposition.','Deal with additional enemies when they prevent safe movement.','Use supplies before the situation becomes unrecoverable.','After an attempt, name one thing to improve: positioning, equipment, timing or preparation.'])+note('These are general combat recommendations. They do not replace an encounter’s specific mechanics, and not every boss attack can be handled in the same way.')),
('Avoid a recovery spiral',p('Do not repeatedly run back alone with no gear or supplies. Pause, ask for help and make a recovery plan. Tell the group where you died and what threat remains there. If the team is not ready, return later rather than spending everyone’s stock on identical attempts.'))
],['Velgar','Imaru','Black_Knight_Titan','Kalphite_Queen','Fuzan','Kuldra'],['launch'],icon='♜',related=['combat','quests','safety'])

add('building','Building guide','Survive & thrive','Make a useful home before making a huge one.',[
('Start with a small, useful space',p('At the shared camp, ask where you may build. A sensible first project is a compact sheltered space with room to move, an available bed and access to storage and workstations. Test the layout before expanding.')+ol(['Choose a permitted area that does not block paths or entrances.','Open Build mode and choose the piece you want.','Read its material requirement and inspect the placement preview.','Place it only when the game accepts the position.','Walk around the finished piece. Check that doors, workstations and other players still have enough space.'])+pic('BuildModeBasic','Build mode separates pieces into categories and shows the selected piece’s requirements.')),
('A functional camp checklist',check('camp-build',['I have permission to build in this spot.','The entrance and nearby paths remain clear.','Beds and workstations can be reached easily.','Storage has a clear purpose or label.','I tested the layout from ground level.','I know how to repair my own pieces.','I checked with the host before a major extension.'])),
('When a piece will not place',ul(['Check whether you have the correct materials, not merely a similar-looking item.','Look for overlap with terrain, other pieces or an occupied space.','Try a simpler ground-level layout and check the current placement rules.','Move away from restricted areas. Some game areas intentionally prevent construction.','Read the preview warning rather than repeatedly clicking the same invalid location.'])),
('Protect the shared village',p('Ask before removing walls, moving workstations or cutting trees close to someone else’s building. A quick change can make another player’s layout unusable. Keep exits obvious and avoid using your build tools while standing beside a structure you do not own.')+p('For larger projects, sketch the footprint first and agree where gathering, cooking, storage and social spaces will go. Keep the working camp usable while the new part is built.'))
],['Construction','Category:Construction'],['build'],icon='⌂',related=['crafting','community','resources'])

add('resources','Resource gathering','Survive & thrive','Know what you need, bring the right tool and make every trip worthwhile.',[
('Plan a gathering trip',ol(['Choose one craft or camp project. Read its missing ingredients.','Bring the appropriate tool and check its condition.','Leave enough carrying capacity for the return journey.','Take supplies and identify a safe route back.','Gather what you came for, then return before a small trip becomes an unplanned expedition.'])),
('Quick resource reference',table(['Resource','How to approach it','What to watch'],[['Loose wood and stone','Look around the starting area and interact with ground items.','A useful way to begin before you have tools.'],['Logs','Equip a suitable axe and target the correct tree.','Tree type and tool requirements matter.'],['Stone and ore','Use a pickaxe appropriate for the deposit.','Read any tool-tier warning.'],['Rune essence','Look for the distinctive floating-rock formations.','Prepare the required runes afterwards; essence is not a finished rune.'],['Food ingredients','Collect appropriate plants or animal drops.','Read descriptions and prepare supplies before travelling.'],['Fibres and hides','Check the recipe, then the Journal entry for its source.','You may need processing before final crafting.'],['Higher-tier materials','Explore only when your tools and equipment are suitable.','A new biome may introduce hazards as well as resources.']],True)),
('Mining: compare the two states',pic('OreNodeMining_Mineable','Mineable deposit example from the host’s screenshots. Inspect the tool and target before mining.')+pic('OreNodeMining_Non_Mineable','Non-mineable example: use the warning on screen to work out what tool or requirement is missing.')+p('If a deposit rejects your tool, swinging again will not solve the requirement. Check that the intended pickaxe is equipped, read the warning and compare the tool against the resource’s requirement. Repair or upgrade as appropriate.')),
('Woodcutting: read before you swing',pic('WoodcuttingHowTo','The target label identifies an Oak Tree; the action prompts tell you how to chop with the equipped axe.')+p('Face the tree closely enough for the target name to appear. Use the appropriate chop action and check that you are receiving the material you need. Do not clear decorative or planted trees around camp without permission.')),
('Bring useful things home',p('Deposit materials in the agreed storage. Keep a small working stock for your own repairs and tell the group when you discover a useful source. Mark a route you can actually repeat safely, not just a location you survived once.')+note('In a hazardous region, learn the environmental protection first. For example, the Bloodblight Swamp’s poison is a reason to prepare antipoison and a retreat route rather than rushing in for its resources.'))
],['Mining','Woodcutting','Rune_Essence','Bloodblight_Swamp'],['tutorial'],icon='◈',related=['crafting','skills','safety'])

add('safety','Keeping yourself safe','Survive & thrive','Protect your character, your supplies and the people playing alongside you.',[
('Before leaving camp',check('safe-trip',['I checked my health and current status effects.','I packed usable food and supplies.','My equipment is repaired and actually equipped.','I have room for what I plan to gather.','I know the route home and my return point.','I told someone if I am attempting unfamiliar terrain.'])),
('Health, supplies and hazards',p('Keep food accessible and read the current item effects. Do not rely on old guides that describe a different health system. The 1.0 release notes describe a healing rework and the removal of Wardstone; your current health display and item descriptions are the useful reference.')+ul(['<strong>Poison:</strong> watch the status indicator. Leave the affected area and use the appropriate remedy if available. Plan protection before entering known toxic terrain.','<strong>Falling:</strong> look for a walkable descent. Do not assume a movement spell is available or will save you.','<strong>Water and terrain:</strong> check the landing and escape route before jumping into an unfamiliar area.','<strong>Overconfidence:</strong> a stronger teammate surviving a region does not mean a new character is ready for it.'])),
('If you die',ol(['Stop and read the game’s recovery information. Death consequences depend on world settings.','Check the map and identify where you died.','Prepare a safe return trip or ask the group for help.','Recover only when you can deal with the threat that caused the death.','Afterwards, repair, restock and decide what needs to change before another attempt.'])+note('Do not assume DragonInfinity has a particular death penalty, invulnerability setting or automatic item recovery. Ask the host about the current custom settings.')),
('A shared world needs care',p('The server screenshot shows PvP enabled. Avoid swinging or testing spells next to players. Consent and the host’s rules matter even when the game permits damage. Keep personal chests and unfinished builds intact.')+p('A multiplayer menu may leave the world running. Move somewhere safe before reading a long guide or stepping away; when in doubt, leave the server rather than assuming you have paused it.')),
('Keep accounts safe too',p('Share the server password only through the host’s agreed channels. Never give someone your platform account password, two-factor code or recovery code. Use official game updates and ask the host before installing anything claimed to be required for joining.'))
],['Death','Combat','Bloodblight_Swamp'],['launch'],icon='♧',related=['combat','community','troubleshooting'])

add('tips','Hints, tips & tricks','Survive & thrive','Small habits that make the next session easier.',[
('Ten habits worth learning',ol(['<strong>Plan one useful task.</strong> “Make a better tool” is easier to finish than “collect everything.”','<strong>Read names, not just icons.</strong> Similar-looking materials may have different uses.','<strong>Check what is equipped.</strong> Your best weapon does nothing while sitting unused in your bag.','<strong>Repair on arrival.</strong> Make it part of your camp routine so the next trip starts ready.','<strong>Sort before crafting.</strong> It is easier to understand shortages when your supplies are organised.','<strong>Visit the skill menu after a level.</strong> You may have unlocked something worth practising.','<strong>Return early.</strong> Coming home with a useful haul beats losing time on a preventable recovery.','<strong>Look at the map before running.</strong> A marker can be nearby in a straight line but awkward to reach.','<strong>Explain what you need.</strong> “I’m missing this ingredient for this recipe” gets better help than “crafting is broken.”','<strong>Leave the next player ready.</strong> Replace communal supplies you use and report shortages.'])),
('Do not copy a veteran’s loadout blindly',p('The screenshots were taken with an established character. Their skill levels, armour, spells and supplies are not what you should expect on a new character. Use each image to understand the interface, then choose equipment you can maintain.')),
('When a guide seems wrong',p('Compare its date and game version with yours. Check the current item tooltip, then recent Jagex notes. Custom-server settings can also explain differences. This guide was reviewed on <strong>9 October 2026</strong>; it is a static edition, not an automatically updating wiki.')),
('A useful end-of-session routine',ul(['Return to a safe location.','Repair gear and organise storage.','Record the next material or quest stage you want to work on.','Let the group know about a new route, hazard or useful discovery.','Leave through the game’s normal menu when you finish.']))
],['RuneScape:Dragonwilds_Wiki'],[],icon='✺',related=['skills','crafting','community'])

add('community','Server etiquette','DragonInfinity','A good shared world is built by the people who play in it.',[
('Welcome to DragonInfinity',p('Our server is hosted by <strong>S3RVNetwork</strong>, part of <strong>S3rvStudios</strong>. Ask the host for the current password, settings and any updated rules. This website is a guide, not a live server dashboard.')),
('Keep the camp welcoming',ul(['Respect personal chests. If a container is not clearly communal, ask before taking anything.','Use communal resources thoughtfully and contribute back when you can.','Check before altering buildings, moving stations or cutting trees close to someone’s home.','Help new arrivals find camp and learn one or two systems at a time.','Keep paths and entrances clear.'])),
('Keep the adventure shared',ul(['Coordinate major quest and boss progress with the group.','Give absent players time and help to catch up.','Ask before initiating PvP or using attacks near another player.','Let the host know about bugs, losses or disruptive behaviour with clear details.','When you need help, include the quest name, item or exact error you are seeing.'])),
('Finding help',p('Speak to the host or other players through your usual server communication channel. No public Discord invitation or contact address was supplied with this edition. Use the '+link('troubleshooting','troubleshooting guide')+' for a useful first check, then the topic-specific wiki links for more detail.'))
],['Multiplayer'],[],icon='♙',related=['connect','getting-started','safety'])

add('troubleshooting','Help & troubleshooting','DragonInfinity','Work out what is wrong before you throw away your progress.',[
('Connection problems',disclosure('I cannot find DragonInfinity',p('Check spelling, filters, crossplay and updates in the world browser. Ask the host whether the server is online. Follow '+link('connect','the connection guide')+' to compare your screen with the supplied example.'))+disclosure('The password is rejected',p('Use the latest password from the host. Check capitals and unwanted spaces. Do not post the password or your account details publicly.'))+disclosure('I joined, but the camp is missing',p('Check the world name. You may be in a local world or a similarly named server. Compare your map with '+link('basecamp','the host’s annotated camp route')+'.'))),
('Gameplay problems',disclosure('I cannot mine or chop this resource',p('Check your equipped tool, its condition and the resource requirement. A tool-tier warning needs a suitable tool; repeated swings will not bypass it.'))+disclosure('The recipe is missing or greyed out',p('Check the correct station, recipe category, unlock and exact ingredients. Review processed materials as well as raw materials. See '+link('crafting','crafting')+'.'))+disclosure('My spell is unlocked but does nothing',p('Check assignment, runes, cooldown and targeting. Read '+link('magic','the spell checklist')+'.'))+disclosure('The quest marker is there but nothing happens',p('Read the stage wording and inspect nearby entrances or levels. Check required items and return dialogue. See '+link('quests','quest troubleshooting')+'.'))+disclosure('Why am I weaker than the character in the screenshots?',p('The host used an established character. Skill levels, gear, spells and custom settings can all differ. Start with the first-session guide rather than trying to reproduce the screenshots’ loadout.'))),
('Report a problem clearly',p('Tell the host: the world name, your platform and game version, what you were trying to do, the exact error, and whether it happens again. A screenshot of the problem helps; hide any passwords or private account details.')+note('Avoid deleting characters or saves as a first fix. Diagnose the issue and ask the host before making changes that could lose progress.')),
('Find deeper answers',p('Use site search for a short explanation. If you need exact recipe numbers, spawn locations or a full encounter walkthrough, open the relevant official wiki page from the bottom of the guide. Jagex’s help centre and news pages are useful for controls, troubleshooting and changed features.'))
],['RuneScape:Dragonwilds_Wiki'],['controls','craft','magic'],icon='?',related=['connect','crafting','quests'])

add('glossary','Beginner glossary','DragonInfinity','The words other players use, translated into plain English.',[
('The language of Ashenfall',table(['Term','What it means'],[['Aggro','An enemy’s attention: the player or target it is trying to attack.'],['Anima','Magical energy important to Ashenfall’s setting.'],['Biome / region','An area with its own terrain, resources and hazards.'],['Buff / debuff','A beneficial / harmful effect on your character.'],['Cooldown','The wait before an ability can be used again.'],['Crafting','Turning ingredients into a useful item.'],['Durability','How worn your equipment is; repair it when needed.'],['Equip','Put an item into use, rather than merely carry it.'],['Farm / grind','Repeat an activity to collect materials or gain progress.'],['Hotbar','Quick-access slots for items or equipment.'],['Loot','Items collected from enemies, containers or the world.'],['NPC','A character controlled by the game, often someone you speak to for a quest.'],['Power level / tier','An indicator of equipment progression; separate from a skill’s XP level.'],['PvE / PvP','Fighting game-controlled enemies / fighting other players.'],['Recipe','The requirements and ingredients for making something.'],['Respawn','Appear again after death. Check your world’s recovery rules.'],['Runes','Consumable magical items used to power spells.'],['Stamina','The resource you spend on actions such as movement and fighting.'],['Telegraph','The visual or sound warning before an enemy attack.'],['XP','Experience points used to advance a skill.']],True)),
('Ask one clear question',p('It is fine not to know a term. Try “Which station makes this?” or “What does this warning mean?” and show the relevant screen. Most problems become easier when everyone is talking about the same item or objective.'))
],['RuneScape:Dragonwilds_Wiki'],[],icon='Aa',related=['getting-started','combat','skills'])

add('sources','Sources & credits','DragonInfinity','Where the guide’s instructions, screenshots and update information come from.',[
('This edition',p('Infinity Guide is an independent fan guide for DragonInfinity. Reviewed <strong>9 October 2026</strong>. RuneScape and RuneScape: Dragonwilds are Jagex properties. This site is not endorsed by or affiliated with Jagex. Server hosting: S3RVNetwork, part of S3rvStudios.')),
('Gameplay and updates',p('Instructions draw on Jagex’s help centre, current release announcements, the host’s screenshots and original practical recommendations. Where an older help page conflicts with newer release notes, the newer information takes priority. Every guide has further-reading links.')+ul(['<a href="'+u+'" target="_blank" rel="noopener">'+t+'</a>' for t,u in SOURCES.values()])),
('Wiki links',p('The RuneScape: Dragonwilds Wiki is the deeper reference for individual items, quests and encounters. This edition includes attributed recipe data and adapted guide material from the host-supplied saved wiki pages, with links to each source. Direct automated access to wiki pages was restricted during preparation, so the guide does not claim a complete current audit of the wiki.')+p('<a href="https://dragonwilds.runescape.wiki/" target="_blank" rel="noopener">Visit the RuneScape: Dragonwilds Wiki</a>')),
('Screenshots and artwork',p('Gameplay screenshots were supplied by the DragonInfinity host in RSDW_InfinityGuide.zip. The underlying game visuals belong to their respective owners, including Jagex. Images are used to illustrate the instructions. No external wiki artwork is bundled. The host authorised including the server password and password-entry screenshot for this privately intended guide.')),
('Local preferences and privacy',p('Search runs in your browser. Bookmarks, reading progress, checklists and theme preference are stored on this device when browser storage is available. They do not sync to your game or another device. This site has no analytics, account system or embedded third-party fonts. External links take you to other sites.')+'<button class="button secondary" id="clear-progress">Reset saved guide progress</button><p class="small">You will be asked before this clears your bookmarks, reading progress and checklists.</p>')
],[],[],icon='ⓘ',related=['overview','troubleshooting'])
